function [dp, re] = pump_friction(v, d, l)
%PUMP_FRICTION  The pressure the wall's friction takes from a flow at speed v [m/s] in a bore d [m] over a length l [m] (Darcy, 64/Re
%   laminar, Blasius above Re 2300), and the flow's Reynolds number (at least 1e-9).
%   v: real[1] (passed a plain number)
%   d: real[1] (passed a plain number)
%   l: real[1] (passed a plain number)
%   returns dp: real[1] (passed a plain number)
%   returns re: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    dp = 0;
    re = 0;
    [rho, mu, rho_e, melt] = asils.models.sizepump.pump_fluid();
    re = asils.models.sizedemand.size_max((((rho * v) * d) / mu), 1e-9);
    f = asils.pc.choose((re < 2300), (64 / re), (0.316 * asils.pc.pow_(re, (-(0.25)))));
    dp = (((((f * (l / d)) * rho) * v) * v) / 2);
end
